def head_gender_swap(current_16_bytes: bytes):
    """Given the current 16-byte Rostral (head) asset-data value, return
    (target_16_bytes, target_head_name) for its opposite-gender match, or
    None if nothing's equipped there or it isn't a recognized stock head."""
    if is_unequipped(current_16_bytes):
        return None
    key = current_16_bytes.hex().upper()
    entry = HEAD_GENDER_SWAP.get(key)
    if entry is None:
        return None
    target_hex, target_name = entry
    return bytes.fromhex(target_hex), target_name


def head_gender_of(current_16_bytes: bytes):
    """"Male", "Female", or None (unequipped / not a recognized stock
    head) for the current 16-byte Rostral value, based on its mod ID half."""
    if is_unequipped(current_16_bytes):
        return None
    mod_hex = current_16_bytes[:8].hex().upper()
    if mod_hex == HEAD_MALE_MOD_ID.replace("0x", "").upper():
        return "Male"
    if mod_hex == HEAD_FEMALE_MOD_ID.replace("0x", "").upper():
        return "Female"
    return None


